content:
220        bs.setByteOrder(Endianness::little);
   221      } else if (bs.skipPrefix("MM", 2)) {
   222        bs.setByteOrder(Endianness::big);
   223      }
   224    }
   225
   226    // Attempt to parse the rest as an IFD
   227    return std::make_unique<TiffRootIFD>(this, ifds, bs, bs.getPosition());
   228  }
