   230  std::vector<const TiffIFD*> TiffIFD::getIFDsWithTag(TiffTag tag) const {
   231    vector<const TiffIFD*> matchingIFDs;
   232    if (entries.find(tag) != entries.end()) {
   233      matchingIFDs.push_back(this);
   234    }
   235    for (auto& i : subIFDs) {
   236      vector<const TiffIFD*> t = i->getIFDsWithTag(tag);
   237      matchingIFDs.insert(matchingIFDs.end(), t.begin(), t.end());
   238    }
   239    return matchingIFDs;
   240  }
   241
   242  const TiffIFD* TiffIFD::getIFDWithTag(TiffTag tag, uint32 index) const
   243  {
   244    auto ifds = getIFDsWithTag(tag);
   245    if (index >= ifds.size())
   246      ThrowTPE("failed to find %u ifs with tag 0x%04x", index + 1, tag);
   247    return ifds[index];
   248  }
