   250  TiffEntry* __attribute__((pure)) TiffIFD::getEntryRecursive(TiffTag tag) const {
   251    auto i = entries.find(tag);
   252    if (i != entries.end()) {
   253      return i->second.get();
   254    }
   255    for (auto &j : subIFDs) {
   256      TiffEntry *entry = j->getEntryRecursive(tag);
   257      if (entry)
   258        return entry;
   259    }
   260    return nullptr;
   261  }
