   263  void TiffIFD::checkOverflow() {
   264    TiffIFD* p = this;
   265    int i = 0;
   266    while ((p = p->parent) != nullptr) {
   267      i++;
   268      if (i > 5)
   269        ThrowTPE("TiffIFD cascading overflow.");
   270    }
   271  }
   272
   273  void TiffIFD::add(TiffIFDOwner subIFD) {
   274    checkOverflow();
   275    if (subIFDs.size() > 100)
   276      ThrowTPE("TIFF file has too many SubIFDs, probably broken");
   277    subIFD->parent = this;
   278    subIFDs.push_back(move(subIFD));
   279  }
   280
   281  void TiffIFD::add(TiffEntryOwner entry) {
   282    entry->parent = this;
   283    entries[entry->tag] = move(entry);
   284  }
   285
   286  TiffEntry* TiffIFD::getEntry(TiffTag tag) const {
   287    auto i = entries.find(tag);
   288    if (i == entries.end())
   289      ThrowTPE("Entry 0x%x not found.", tag);
   290    return i->second.get();
   291  }
   292
   293  TiffID TiffRootIFD::getID() const
   294  {
   295    TiffID id;
   296    auto makeE = getEntryRecursive(MAKE);
   297    auto modelE = getEntryRecursive(MODEL);
   298
   299    if (!makeE)
   300      ThrowTPE("Failed to find MAKE entry.");
   301    if (!modelE)
   302      ThrowTPE("Failed to find MODEL entry.");
   303
   304    id.make = trimSpaces(makeE->getString());
   305    id.model = trimSpaces(modelE->getString());
   306
   307    return id;
   308  }
